                range.right = .{ .op = .lt };
                if (version.minor) |minor| {
                    _ = &minor;
                    range.left.version.minor = minor;
                    if (version.patch) |patch| {
                        _ = &patch;
                        range.left.version.patch = patch;
                        range.left.version.tag = version.tag;
                    }
                    range.right.version.major = major;
                    range.right.version.minor = (minor +| 1);
                } else {
                    range.right.version.major = (major +| 1);
                }
            }
            return range;
},
.none => {
_ = unreachable;
},
.version => {
if ((self.wildcard != Wildcard.none)) {
                return Range.initWildcard(version.min(), self.wildcard);
            }
            return .{ .left = .{ .op = .eql, .version = version.min() } };
},
else => {

},
}
            return (switch (self.wildcard) {
.major => .{ .left = .{ .op = .gte, .version = version.min() }, .right = .{ .op = .lte, .version = .{ .major = std.math.maxInt(u64), .minor = std.math.maxInt(u64), .patch = std.math.maxInt(u64) } } },
.minor => (switch (self.tag) {
.lte => .{ .left = .{ .op = .lte, .version = .{ .major = ((version.major) orelse (0)), .minor = std.math.maxInt(u64), .patch = std.math.maxInt(u64) } } },
.lt => .{ .left = .{ .op = .lt, .version = .{ .major = ((version.major) orelse (0)), .minor = 0, .patch = 0 } } },
.gt => .{ .left = .{ .op = .gt, .version = .{ .major = ((version.major) orelse (0)), .minor = std.math.maxInt(u64), .patch = std.math.maxInt(u64) } } },
.gte => .{ .left = .{ .op = .gte, .version = .{ .major = ((version.major) orelse (0)), .minor = 0, .patch = 0 } } },
else => unreachable,
}),
.patch => (switch (self.tag) {
.lte => .{ .left = .{ .op = .lte, .version = .{ .major = ((version.major) orelse (0)), .minor = ((version.minor) orelse (0)), .patch = std.math.maxInt(u64) } } },
.lt => .{ .left = .{ .op = .lt, .version = .{ .major = ((version.major) orelse (0)), .minor = ((version.minor) orelse (0)), .patch = 0 } } },
.gt => .{ .left = .{ .op = .gt, .version = .{ .major = ((version.major) orelse (0)), .minor = ((version.minor) orelse (0)), .patch = std.math.maxInt(u64) } } },
.gte => .{ .left = .{ .op = .gte, .version = .{ .major = ((version.major) orelse (0)), .minor = ((version.minor) orelse (0)), .patch = 0 } } },
else => unreachable,
}),
.none => .{ .left = .{ .op = (switch (self.tag) {
.gt => .gt,
.gte => .gte,
.lt => .lt,
.lte => .lte,
else => unreachable,
}), .version = version.min() } },
});
    }
    pub const Tag = enum {
                none,
                gt,
                gte,
                lt,
                lte,
                version,
                tilda,
                caret,
            };
    pub const Wildcard = enum {
                none,
                major,
                minor,
                patch,
            };
};

pub fn fmt(self: *const Query, buf: []const u8) Formatter {
        return .{ .query = self, .buffer = buf };
}

pub fn eql(lhs: *const Query, rhs: *const Query) bool {
        if ((!lhs.range.eql(rhs.range))) {
            return false;
        }
        const lhs_next = ((lhs.next) orelse { return (rhs.next == null); });
        const rhs_next = ((rhs.next) orelse { return false; });
        return lhs_next.eql(rhs_next);
}

pub fn satisfies(query: *const Query, version: Version, query_buf: []const u8, version_buf: []const u8) bool {
        return (query.range.satisfies(version, query_buf, version_buf) and ((query.next) orelse { return true; }).satisfies(version, query_buf, version_buf));
}

pub fn satisfiesPre(query: *const Query, version: Version, query_buf: []const u8, version_buf: []const u8, pre_matched: *bool) bool {
        if (comptime Environment.allow_assert) {
            _ = assert(version.tag.hasPre());
        }
        return (query.range.satisfiesPre(version, query_buf, version_buf, pre_matched) and ((query.next) orelse { return true; }).satisfiesPre(version, query_buf, version_buf, pre_matched));
}

pub fn parse(allocator: Allocator, input: []const u8, sliced: SlicedString) bun.OOM!Group {
        var i: usize = 0;
        _ = &i;
        var list = Group{ .allocator = allocator, .input = input };
        _ = &list;
        var token = Token{  };
        _ = &token;
        var prev_token = Token{  };
        _ = &prev_token;
        var count: u8 = 0;
        _ = &count;
        var skip_round = false;
        _ = &skip_round;
        var is_or = false;
        _ = &is_or;
        while ((i < input.len)) {
            skip_round = false;
            switch (input[@as(usize, @intCast(i))]) {
'>' => {
if (((input.len > (i + 1)) and (input[@as(usize, @intCast((i + 1)))] == 61))) {
                token.tag = .gte;
                i = (i + 1);
            } else {
                token.tag = .gt;
            }
            i = (i + 1);
            while (((i < input.len) and (input[@as(usize, @intCast(i))] == 32))) {
                i = (i + 1);
            }
},
'<' => {
if (((input.len > (i + 1)) and (input[@as(usize, @intCast((i + 1)))] == 61))) {
                token.tag = .lte;
                i = (i + 1);
            } else {
                token.tag = .lt;
            }
            i = (i + 1);
            while (((i < input.len) and (input[@as(usize, @intCast(i))] == 32))) {
                i = (i + 1);
            }
},
'=', 'v' => {
token.tag = .version;
            is_or = true;
            i = (i + 1);
            while (((i < input.len) and (input[@as(usize, @intCast(i))] == 32))) {
                i = (i + 1);
            }
},
'~' => {
token.tag = .tilda;
            i = (i + 1);
            if (((i < input.len) and (input[@as(usize, @intCast(i))] == 62))) {
                i = (i + 1);
            }
            while (((i < input.len) and (input[@as(usize, @intCast(i))] == 32))) {
                i = (i + 1);
            }
},
'^' => {
token.tag = .caret;
            i = (i + 1);
            while (((i < input.len) and (input[@as(usize, @intCast(i))] == 32))) {
                i = (i + 1);
            }
},
48...57, 'X', 'x', '*' => {
token.tag = .version;
            is_or = true;
},
'|' => {
i = (i + 1);
            while (((i < input.len) and (input[@as(usize, @intCast(i))] == 124))) {
                i = (i + 1);
            }
            while (((i < input.len) and (input[@as(usize, @intCast(i))] == 32))) {
                i = (i + 1);
            }
            is_or = true;
            token.tag = Token.Tag.none;
            skip_round = true;
},
'-' => {
i = (i + 1);
            while (((i < input.len) and (input[@as(usize, @intCast(i))] == 32))) {
                i = (i + 1);
            }
},
' ' => {
i = (i + 1);
            while (((i < input.len) and (input[@as(usize, @intCast(i))] == 32))) {
                i = (i + 1);
            }
            skip_round = true;
},
else => {
i = (i + 1);
            token.tag = Token.Tag.none;
            while ((((i < input.len) and (input[@as(usize, @intCast(i))] != 32)) and (input[@as(usize, @intCast(i))] != 124))) {
                i = (i + 1);
            }
            skip_round = true;
},
}
            if ((!skip_round)) {
                const parse_result = Version.parse(sliced.sub(input[i..]));
                const version = parse_result.version.min();
                if (version.tag.hasBuild()) {
                    _ = list.flags.setValue(Group.Flags.build, true);
                }
                if (version.tag.hasPre()) {
                    _ = list.flags.setValue(Group.Flags.pre, true);
                }
                token.wildcard = parse_result.wildcard;
                i = (i + parse_result.len);
                const rollback = i;
                const maybe_hyphenate = ((i < input.len) and ((input[@as(usize, @intCast(i))] == 32) or (input[@as(usize, @intCast(i))] == 45)));
                const hyphenate: bool = (maybe_hyphenate and possibly_hyphenate: {
                i = (i + strings.lengthOfLeadingWhitespaceASCII(input[i..]));
                if ((!((i < input.len) and (input[@as(usize, @intCast(i))] == 45)))) {
                    break :possibly_hyphenate false;
                }
                i = (i + 1);
                i = (i + strings.lengthOfLeadingWhitespaceASCII(input[i..]));
                if ((i == input.len)) {
                    break :possibly_hyphenate false;
                }
                if (((input[@as(usize, @intCast(i))] == 118) or (input[@as(usize, @intCast(i))] == 61))) {
                    i = (i + 1);
                }
                if ((i == input.len)) {
                    break :possibly_hyphenate false;
                }
                i = (i + strings.lengthOfLeadingWhitespaceASCII(input[i..]));
                if ((i == input.len)) {
                    break :possibly_hyphenate false;
                }
                if ((!((i < input.len) and (switch (input[@as(usize, @intCast(i))]) {
48...57, 'X', 'x', '*' => true,
else => false,
})))) {
                    break :possibly_hyphenate false;
                }
                break :possibly_hyphenate true;
});
                if ((!hyphenate)) {
                    i = rollback;
                }
                i = (i + (if (comptime @typeInfo(@TypeOf(@intFromBool((!hyphenate)))) == .@"enum") cp_cast_int(usize, @intFromEnum(@intFromBool((!hyphenate)))) else cp_cast_int(usize, @intFromBool((!hyphenate)))));
                if (hyphenate) {
                    const second_parsed = Version.parse(sliced.sub(input[i..]));
                    var second_version = second_parsed.version.min();
                    _ = &second_version;
                    if (second_version.tag.hasBuild()) {
                        _ = list.flags.setValue(Group.Flags.build, true);
                    }
                    if (second_version.tag.hasPre()) {
                        _ = list.flags.setValue(Group.Flags.pre, true);
                    }
                    const range: Range = brk: {
                    break :brk (switch (second_parsed.wildcard) {
.major => break :brk Range{ .left = .{ .op = .gte, .version = version } },
.minor => {
{
                        second_version.major = (second_version.major +| 1);
                        second_version.minor = 0;
                        second_version.patch = 0;
                        break :brk Range{ .left = .{ .op = .gte, .version = version }, .right = .{ .op = .lt, .version = second_version } };
                    }
},
.patch => {
{
                        second_version.minor = (second_version.minor +| 1);
                        second_version.patch = 0;
                        break :brk Range{ .left = .{ .op = .gte, .version = version }, .right = .{ .op = .lt, .version = second_version } };
                    }
},
.none => break :brk Range{ .left = .{ .op = .gte, .version = version }, .right = .{ .op = .lte, .version = second_version } },
});

};
                    if (is_or) {
                        _ = try list.orRange(range);
                    } else {
                        _ = try list.andRange(range);
                    }
                    i = (i + (second_parsed.len + 1));
                } else {
                    if (((count == 0) and (token.tag == .version))) {
                        switch (parse_result.wildcard) {
.none => {
_ = try list.orVersion(version);
},
else => {
_ = try list.orRange(token.toRange(parse_result.version));
},
}
                    } else {
                        if ((count == 0)) {
                            if ((token.tag == .none)) {
                                is_or = false;
                                token.wildcard = .none;
                                prev_token.tag = .none;
                                continue;
                            }
                            _ = try list.andRange(token.toRange(parse_result.version));
                        } else {
                            if (is_or) {
                                _ = try list.orRange(token.toRange(parse_result.version));
                            } else {
                                _ = try list.andRange(token.toRange(parse_result.version));
                            }
                        }
                    }
                }
                is_or = false;
                count = (count + 1);
                token.wildcard = .none;
                prev_token.tag = token.tag;
            }
        }
        return list;
}
